// Each candidate is generated by the user's trained ZeroAI model, not an API.
import {ByteLevelBPE} from './tokenizer.js';
import {ZeroAIModel} from './model.js';
import {logProbability,paraphraseNumericQuestion} from './quality_v17.js';
import {rankV18,relationParaphrases} from './quality_v18.js';
import {routeMath} from './math_v18_fix.js';
import {makeConversationPrompt,HISTORY_TOKEN_LIMIT} from './context_memory.js';
import {checkGeneratedQuality} from './quality_guard.js';
import {newUtf8State,sampleUtf8Token} from './utf8_sampling.js';
let model=null,tok=null;
function report(type,fields={}){self.postMessage({type,...fields});}
self.onmessage=async event=>{
  const d=event.data;
  try{
    if(d.type==='load'){
      model=new ZeroAIModel(d.manifest,d.weights);tok=new ByteLevelBPE(d.tokenizer);
      for(const [token,id] of Object.entries(d.manifest.special_token_ids))
        if(tok.special[token]!==id)throw Error('Tokenizer special ID mismatch: '+token);
      report('ready',{step:d.manifest.checkpoint_step,vocab:model.cfg.vocab_size,context:model.maxContext,trainedContext:model.trainedContext,historyLimit:HISTORY_TOKEN_LIMIT,experimental:true});
    }else if(d.type==='generate'){
      if(!model||!tok)throw Error('Model not loaded');
      const question=String(d.question||'').trim();
      if(!question)throw Error('質問を入力してね');
      const codeMode=!!d.codeMode;
      const calculated=routeMath(question,{codeMode,wordProblems:!!d.useMath});
      if(calculated){report('done',{output:calculated.answer,tokens:0,candidates:[],verification:'ローカル四則演算（GPT生成ではありません）',source:'local_calculation',question,codeMode:false,math:calculated});return;}
      const requestedCandidates=Math.max(1,Math.min(4,Math.trunc(Number(d.candidates)||1)));
      const wantedOutput=Math.max(8,Math.min(160,Math.trunc(Number(d.maxTokens)||64)));
      const requestedLimit=Math.trunc(Number(d.contextLimit)||model.maxContext);
      // A newly trained 1024/2048 model must still allow an independent 512-token stable mode.
      const contextLimit=Math.max(512,Math.min(model.maxContext,requestedLimit));
      const alt=codeMode?paraphraseNumericQuestion(question):null;
      let questions=codeMode?(alt?[question,alt]:[question]):[question,...relationParaphrases(question)];
      report('phase',{stage:'tokenize',text:'文章をトークンに変換しています…'});
      const primary=makeConversationPrompt(tok,d.history,question,contextLimit,wantedOutput);
      const largePrompt=primary.ids.length>model.trainedContext;
      // Large prompts use one candidate; otherwise multiplying large KV caches
      // by candidate count would exhaust phone and laptop browser memory.
      if(largePrompt)questions=[question];
      const nCandidates=largePrompt?1:requestedCandidates;
      const contextData=questions.map((q,i)=>i===0?primary:makeConversationPrompt(
        tok,d.history,q,contextLimit,wantedOutput));
      const maxNew=Math.min(wantedOutput,contextLimit-Math.max(...contextData.map(c=>c.ids.length)));
      if(maxNew<1)throw Error('No tokens left for generating the answer');
      const exceedsTrained=primary.ids.length>model.trainedContext;
      report('notice',{text:`${exceedsTrained?'【未学習の長文領域を使用】':'【学習済みの文脈内】'} 入力 ${primary.ids.length.toLocaleString()} tokens / 上限 ${contextLimit.toLocaleString()} tokens。モデルの学習時文脈は${model.trainedContext} tokensです。`});
      const starts=[];
      for(let i=0;i<contextData.length;i++){
        const ctx=contextData[i];
        const capacity=Math.min(contextLimit,ctx.ids.length+wantedOutput+3);
        const session=model.session(capacity);
        // Token-by-token real full-attention prefill. Report actual processed
        // token counts, not an artificial countdown/estimated progress.
        const logits=await session.prefillAsync(ctx.ids,{
          yieldEvery:ctx.ids.length>1000?2:8,
          progressEvery:ctx.ids.length>1000?4:16,
          onProgress:(done,total)=>report('prefill',{
            done,total,variant:i+1,variants:contextData.length,
            percent:Math.round(done*100/Math.max(1,total)),
            trainedContext:model.trainedContext,contextLimit
          })
        });
        starts.push({session,logits,length:ctx.ids.length,ctx});
      }
      const stopIds=new Set([tok.special['<end>'],tok.special['<user>'],tok.special['<bot>'],tok.special['<eof>']]);
      const candidates=[];
      for(let c=0;c<nCandidates;c++){
        const variant=c%questions.length;
        const useAlt=variant!==0;
        const start=starts[variant];
        const session=nCandidates===1?start.session:start.session.clone();let logits=start.logits;
        let result=[],sumLP=0,stopped=false,utf8State=newUtf8State(),lastComplete=0;
        // Use controlled sampling for the 10k experimental mode; greedy Top-1
        // causes pathological self-repetition in long untrained contexts.
        const deterministic=!largePrompt&&(c===0||(useAlt&&c===1));
        const temp=largePrompt?Math.max(0.68,Math.min(0.9,Number(d.temperature)||0.72))
          :(deterministic?0.45:(Number(d.temperature)||0.62));
        const topK=largePrompt?Math.max(15,Math.min(40,Math.trunc(Number(d.topK)||25)))
          :(deterministic?1:Math.max(2,Number(d.topK)||25));
        const topP=(deterministic?1:(Number(d.topP)||0.95));
        report('notice',{text:`端末内で候補 ${c+1}/${nCandidates} を生成中…${useAlt?'（質問を言い換え）':''}`});
        for(let t=0;t<maxNew+3&&session.pos<session.capacity;t++){
          if(t>=maxNew&&utf8State.need===0)break;
          // Choose BPE tokens whose bytes can form valid UTF-8 across token
          // boundaries, and never stop on an unfinished Japanese character.
          const choice=sampleUtf8Token(logits,tok,utf8State,stopIds,temp,topK,topP);
          const next=choice.id;
          if(stopIds.has(next)){stopped=true;break;}
          utf8State=choice.state;
          result.push(next);sumLP+=logProbability(logits,next);
          if(utf8State.need===0)lastComplete=result.length;
          if(c===0&&(t%3===0||t===maxNew-1))
            report('progress',{output:tok.decodePartial(result),tokens:result.length});
          logits=session.step(next);
          if(t%4===3)await new Promise(resolve=>setTimeout(resolve,0));
        }
        // If the context limit ends mid-character, discard ONLY incomplete
        // trailing bytes and report the truncation instead of displaying �.
        const complete=result.slice(0,lastComplete);
        candidates.push({text:tok.decode(complete),tokens:complete.length,
          incompleteSuffixTokens:result.length-lastComplete,
          avgLogprob:result.length?sumLP/result.length:-100,stopped,
          source:useAlt?'言い換え':'原文'});
      }
      report('phase',{stage:'rank',text:'生成結果を確認しています…'});
      const result=rankV18(question,candidates,codeMode);
      const checks=candidates.map(c=>c.incompleteSuffixTokens>0
        ?{ok:false,code:'incomplete_utf8',reason:'文字の途中で生成上限に達しました'}
        :checkGeneratedQuality(c.text));
      let selectedIndex=result.index;
      if(!checks[selectedIndex].ok){
        const valid=candidates.map((c,i)=>({i,score:result.reports[i].score}))
          .filter(x=>checks[x.i].ok).sort((a,b)=>b.score-a.score);
        if(valid.length)selectedIndex=valid[0].i;
      }
      const picked=candidates[selectedIndex],quality=checks[selectedIndex];
      // Do not pretend corrupt or looping output is a valid model answer.
      // Original text remains accessible in diagnostics for debugging.
      const displayed=quality.ok?picked.text:
        'ZeroAIの回答が不安定になりました（'+quality.reason+'）。'+
        '正確な回答を作れなかったため、出力を停止しました。'+
        '512トークン（安定版）または短い文章で再試行してください。';
      report('done',{output:displayed,rawOutput:picked.text,
        qualityWarning:quality.ok?null:{code:quality.code,reason:quality.reason},
        tokens:picked.tokens,
        bestIndex:selectedIndex,candidates:candidates.map((c,i)=>({text:c.text,tokens:c.tokens,
        avgLogprob:c.avgLogprob,score:result.reports[i].score,reason:result.reports[i].reason,
        selected:i===selectedIndex,source:c.source})),verification:result.reports[selectedIndex].verification,source:'gpt',question,codeMode,
        contextInfo:{historyLimit:HISTORY_TOKEN_LIMIT,inferenceContext:contextLimit,trainedContext:model.trainedContext,experimental:true,
        retainedHistoryTokens:contextData[0].retainedHistoryTokens,
        usedHistoryTokens:starts[selectedIndex%starts.length]?.ctx.usedHistoryTokens||0,
        promptTokens:contextData[0].promptTokenCount,keptTurns:contextData[0].keptTurns,
        truncatedQuestion:contextData[0].truncatedQuestion}});
    }
  }catch(e){report('error',{error:String(e?.message||e)});}
};
